rules.logic:
element.style.position = 'fixed';
element.style.top = '10px';
element.style.right = '10px';
element.style.width = '220px';
element.style.maxHeight = 'calc(100vh - 20px)';
element.style.overflowY = 'auto';
element.style.zIndex = '999';
element.style.boxShadow = '0 2px 8px rgba(0,0,0,0.2)';
element.style.margin = '0';

element.style.listStyle = 'none';
element.style.padding = '0';
element.style.margin = '0';
element.style.display = 'flex';
element.style.flexWrap = 'wrap';
element.style.gap = '1px 4px';

var items = element.querySelectorAll('li');
for (var i = 0; i < items.length; i++) {
    var li = items[i];
    li.style.display = 'inline';
    li.style.padding = '0';
    li.style.margin = '0';
    li.style.listStyle = 'none';
}

var links = element.querySelectorAll('a');
for (var i = 0; i < links.length; i++) {
    links[i].style.fontSize = '0.8em';
    links[i].style.whiteSpace = 'nowrap';
}

element.style.fontSize = '0.85em';
element.style.lineHeight = '1.3';
element.style.padding = '6px 8px';

var paragraphs = element.querySelectorAll('p');
for (var i = 0; i < paragraphs.length; i++) {
    paragraphs[i].style.margin = '4px 0';
    paragraphs[i].style.fontSize = '0.9em';
}

element.style.fontSize = '0.85em';
element.style.lineHeight = '1.2';
element.style.marginBottom = '0.3em';
element.style.textAlign = 'left';

var spans = element.querySelectorAll('span');
for (var i = 0; i < spans.length; i++) {
    spans[i].style.fontSize = '0.95em';
}
